entries[104038] = { ["name"] = "Cursed Swabby Helmet", ["text"] = "Binds when picked up\nUnique\nUse: Transform into a Cursed Hozen Swabby, able to breathe underwater and swim 200% faster.\n\nOnly useable in Pandaria. (1 Hour Cooldown)\n\"Used to transform lowly swabbies into mindless hozen brutes, able to row the dread ship Vazuviuz.\"" }
entries[104046] = { ["name"] = "Glyph of Swift Death", ["text"] = "Major Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nThe haste effect granted by Soul Reaper now also increases your movement speed by 30% for the duration.\nSell Price:" }
entries[104047] = { ["name"] = "Glyph of Loud Horn", ["text"] = "Major Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Horn of Winter now generates an additional 10 Runic Power, but the cooldown is increased by 100%.\nSell Price:" }
entries[104048] = { ["name"] = "Glyph of Regenerative Magic", ["text"] = "Major Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIf Anti-Magic Shell expires after its full duration, the cooldown is reduced by up to 50%, based on the amount of damage absorbtion remaining.\nSell Price:" }
entries[104049] = { ["name"] = "Glyph of Festering Blood", ["text"] = "Major Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nBlood Boil will now treat all targets as though they have Blood Plague or Frost Fever applied.\nSell Price:" }
entries[104050] = { ["name"] = "Glyph of Divine Shield", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nRemoving harmful effects with Divine Shield heals you for 10% for each effect removed. This heal cannot exceed 50% of your maximum health.\nSell Price:" }
entries[104051] = { ["name"] = "Glyph of Hand of Sacrifice", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nHand of Sacrifice no longer redirects damage to the Paladin.\nSell Price:" }
entries[104052] = { ["name"] = "Glyph of Purging", ["text"] = "Major Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nSuccessfully Purging a target now grants a stack of Maelstrom Weapon.\nSell Price:" }
entries[104053] = { ["name"] = "Glyph of Eternal Earth", ["text"] = "Major Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Lightning Bolt has a chance to add a charge to your currently active Earth Shield. This cannot cause Earth Shield to exceed 9 charges.\nSell Price:" }
entries[104054] = { ["name"] = "Glyph of Havoc", ["text"] = "Major Glyph\nClasses: Warlock\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nHavoc gains 3 additional charges, but the cooldown is increased by 35 seconds.\nSell Price:" }
entries[104055] = { ["name"] = "Glyph of Impaling Throws", ["text"] = "Major Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nHeroic Throw now leaves an axe in the target, which can be retrieved by moving within 5 yards of the target to finish the cooldown of Heroic Throw. This effect will only occur when Heroic Throw is cast from more than 10 yards away from the target.\nSell Price:" }
entries[104056] = { ["name"] = "Glyph of the Executor", ["text"] = "Major Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nKilling an enemy with Execute grants you 30 rage.\nSell Price:" }
entries[104099] = { ["name"] = "Glyph of the Skeleton", ["text"] = "Minor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Raise Dead spell summons a skeleton instead of a ghoul.\nSell Price:" }
entries[104101] = { ["name"] = "Glyph of the Long Winter", ["text"] = "Minor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nThe effect of your Horn of Winter now lasts for 1 hour.\nSell Price:" }
entries[104102] = { ["name"] = "Glyph of the Sprouting Mushroom", ["text"] = "Minor Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Wild Mushroom spell can now be placed on the ground instead of underneath a target.\nSell Price:" }
entries[104103] = { ["name"] = "Glyph of One with Nature", ["text"] = "Minor Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nGrants you the ability to teleport to a random natural location.\nSell Price:" }
entries[104104] = { ["name"] = "Glyph of the Unbound Elemental", ["text"] = "Minor Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Water Elemental is replaced by an Unbound Water Elemental.\nSell Price:" }
entries[104105] = { ["name"] = "Glyph of Evaporation", ["text"] = "Minor Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nReduces the size of your Water Elemental by 40%.\nSell Price:" }
entries[104106] = { ["name"] = "Glyph of Condensation", ["text"] = "Minor Glyph\nClasses: Mage\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the size of your Water Elemental by 40%.\nSell Price:" }
entries[104107] = { ["name"] = "Glyph of the Exorcist", ["text"] = "Minor Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nExorcism will now appear to remove the evil from its target.\nSell Price:" }
entries[104108] = { ["name"] = "Glyph of Pillar of Light", ["text"] = "Minor Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nCritical heals on other players display a small pillar of light at their location briefly.\nSell Price:" }
entries[104109] = { ["name"] = "Glyph of Angels", ["text"] = "Minor Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour heal spells momentarily grant you angelic wings. (100ms cooldown)\nSell Price:" }
entries[104110] = { ["name"] = "Curious Bronze Timepiece", ["text"] = "Quest Item\nUnique\nRequires Level 90\nUse: Teleports you to Watcher Alundra upon the Timeless Isle.\n\"The hour markings are illegible, and hurt one's eyes to focus upon.\"" }
entries[104111] = { ["name"] = "Elixir of Wandering Spirits", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Take on the form of a Golden Lotus hero. (3 Sec Cooldown)\nSell Price:" }
entries[104112] = { ["name"] = "Curious Ticking Parcel", ["text"] = "Requires Level 90\n<Right Click to Open>" }
entries[104113] = { ["name"] = "Curious Bronze Timepiece", ["text"] = "Quest Item\nUnique\nRequires Level 90\nUse: Teleports you to Watcher Lara upon the Timeless Isle.\n\"The hour markings are illegible, and hurt one's eyes to focus upon.\"" }
entries[104114] = { ["name"] = "Curious Ticking Parcel", ["text"] = "Requires Level 90\n<Right Click to Open>" }
entries[104115] = { ["name"] = "Mist-Filled Spirit Lantern", ["text"] = "Binds when picked up\nUnique\nDuration: 1 hour (real time)\nUse: Summon the Dread Ship Vazuvius from the depths.\n\"A strange, lifelike mist is trapped within this small lantern.\"" }
entries[104120] = { ["name"] = "Glyph of the Sha", ["text"] = "Minor Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nTransforms your Shadowfiend and Mindbender into a Sha Beast.\nSell Price:" }
entries[104121] = { ["name"] = "Glyph of Shifted Appearances", ["text"] = "Minor Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nVoid Shift causes you and your target to exchange appearances for several seconds.\n\nDoes not affect mounted players.\nSell Price:" }
entries[104122] = { ["name"] = "Glyph of Inspired Hymns", ["text"] = "Minor Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhile channeling Hymns, a spirit appears above you.\nSell Price:" }
entries[104123] = { ["name"] = "Glyph of Headhunting", ["text"] = "Minor Glyph\nClasses: Rogue\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Throw and Deadly Throw abilities will now throw axes regardless of your currently equipped weapon.\nSell Price:" }
entries[104124] = { ["name"] = "Glyph of Improved Distraction", ["text"] = "Minor Glyph\nClasses: Rogue\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nDistract now summons a decoy at the target location.\nSell Price:" }
entries[104126] = { ["name"] = "Glyph of Spirit Raptors", ["text"] = "Minor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Spirit Wolves are replaced with Spirit Raptors.\nSell Price:" }
entries[104127] = { ["name"] = "Glyph of Lingering Ancestors", ["text"] = "Minor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nResurrecting someone with Ancestral Spirit causes a ghostly ancestor to follow them around for a short time.\nSell Price:" }
entries[104128] = { ["name"] = "Glyph of Spirit Wolf", ["text"] = "Minor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nGhost Wolf can be now be used while you are a ghost.\nSell Price:" }
entries[104129] = { ["name"] = "Glyph of Flaming Serpent", ["text"] = "Minor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Searing Totem now resembles Vol'jin's Serpent Ward.\nSell Price:" }
entries[104130] = { ["name"] = "Glyph of the Compy", ["text"] = "Minor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Hex now transforms enemies into a Compy.\nSell Price:" }
entries[104131] = { ["name"] = "Glyph of Elemental Familiars", ["text"] = "Minor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nSummons a random Fire, Water, or Nature familiar. Familiars of different types have a tendency to fight each other.\nSell Price:" }
entries[104133] = { ["name"] = "Glyph of Astral Fixation", ["text"] = "Minor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nAstral Recall now takes you to your capital's Earthshrine.\nSell Price:" }
entries[104134] = { ["name"] = "Glyph of Rain of Frogs", ["text"] = "Minor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou summon a rain storm of frogs at your targeted location.\nSell Price:" }
entries[104135] = { ["name"] = "Glyph of the Raging Whirlwind", ["text"] = "Minor Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhirlwind gives you 15 rage over 6 sec, but for that time you no longer generate rage from autoattacks.\nSell Price:" }
entries[104136] = { ["name"] = "Glyph of the Subtle Defender", ["text"] = "Minor Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nRemoves the threat generation bonus from Defensive Stance.\nSell Price:" }
entries[104137] = { ["name"] = "Glyph of the Watchful Eye", ["text"] = "Minor Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIntervene will now target the party or raid member with the lowest health within 25 yards.\nSell Price:" }
entries[104138] = { ["name"] = "Glyph of the Weaponmaster", ["text"] = "Minor Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Shout abilities cause the appearance of your weapon to change to that of a random weapon from your primary bag for 10 min.\nSell Price:" }
