entries[104197] = { ["name"] = "Technique: Glyph of Swift Death", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Swift Death.\n\nGlyph of Swift Death\nMajor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nThe haste effect granted by Soul Reaper now also increases your movement speed by 30% for the duration.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104198] = { ["name"] = "Mantid Artifact Hunter's Kit", ["text"] = "Binds when picked up\n\"Contains a Mantid Artifact Sonic Locator, which causes any new digsites you discover in Pandaria to be of Mantid origin for a day. Also contains a Lorewalker's Map.\"\n<Right Click to Open>" }
entries[104202] = { ["name"] = "Bonkers", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss Bonkers the Boxing Hozen.\nSell Price:" }
entries[104208] = { ["name"] = "Reins of Galakras", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 90\nRequires Artisan Riding\nUse: Teaches you how to summon a Spawn of Galakras. This is a flying mount." }
entries[104209] = { ["name"] = "Technique: Glyph of Loud Horn", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Loud Horn.\n\nGlyph of Loud Horn\nMajor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Horn of Winter now generates an additional 10 Runic Power, but the cooldown is increased by 100%.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104210] = { ["name"] = "Technique: Glyph of Regenerative Magic", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Regenerative Magic.\n\nGlyph of Regenerative Magic\nMajor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIf Anti-Magic Shell expires after its full duration, the cooldown is reduced by up to 50%, based on the amount of damage absorbtion remaining.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104211] = { ["name"] = "Technique: Glyph of Festering Blood", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Festering Blood.\n\nGlyph of Festering Blood\nMajor Glyph\nClasses: Death Knight\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nBlood Boil will now treat all targets as though they have Blood Plague or Frost Fever applied.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104212] = { ["name"] = "Technique: Glyph of Divine Shield", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Divine Shield.\n\nGlyph of Divine Shield\nMajor Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nRemoving harmful effects with Divine Shield heals you for 10% for each effect removed. This heal cannot exceed 50% of your maximum health.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104213] = { ["name"] = "Technique: Glyph of Hand of Sacrifice", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Hand of Sacrifice.\n\nGlyph of Hand of Sacrifice\nMajor Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nHand of Sacrifice no longer redirects damage to the Paladin.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104214] = { ["name"] = "Technique: Glyph of Purging", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Purging.\n\nGlyph of Purging\nMajor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nSuccessfully Purging a target now grants a stack of Maelstrom Weapon.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104215] = { ["name"] = "Technique: Glyph of Eternal Earth", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Eternal Earth.\n\nGlyph of Eternal Earth\nMajor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Lightning Bolt has a chance to add a charge to your currently active Earth Shield. This cannot cause Earth Shield to exceed 9 charges.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104216] = { ["name"] = "Technique: Glyph of Havoc", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Havoc.\n\nGlyph of Havoc\nMajor Glyph\nClasses: Warlock\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nHavoc gains 3 additional charges, but the cooldown is increased by 35 seconds.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
