entries[104230] = { ["name"] = "Technique: Glyph of Shifted Appearances", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Shifted Appearances.\n\nGlyph of Shifted Appearances\nMinor Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nVoid Shift causes you and your target to exchange appearances for several seconds.\n\nDoes not affect mounted players.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104231] = { ["name"] = "Technique: Glyph of Inspired Hymns", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Inspired Hymns.\n\nGlyph of Inspired Hymns\nMinor Glyph\nClasses: Priest\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhile channeling Hymns, a spirit appears above you.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104232] = { ["name"] = "Technique: Glyph of Headhunting", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Headhunting.\n\nGlyph of Headhunting\nMinor Glyph\nClasses: Rogue\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Throw and Deadly Throw abilities will now throw axes regardless of your currently equipped weapon.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104233] = { ["name"] = "Technique: Glyph of Improved Distraction", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Improved Distraction.\n\nGlyph of Improved Distraction\nMinor Glyph\nClasses: Rogue\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nDistract now summons a decoy at the target location.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104234] = { ["name"] = "Technique: Glyph of Spirit Raptors", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Spirit Raptors.\n\nGlyph of Spirit Raptors\nMinor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Spirit Wolves are replaced with Spirit Raptors.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104235] = { ["name"] = "Technique: Glyph of Lingering Ancestors", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Lingering Ancestors.\n\nGlyph of Lingering Ancestors\nMinor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nResurrecting someone with Ancestral Spirit causes a ghostly ancestor to follow them around for a short time.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104236] = { ["name"] = "Technique: Glyph of Spirit Wolf", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Spirit Wolf.\n\nGlyph of Spirit Wolf\nMinor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nGhost Wolf can be now be used while you are a ghost.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104237] = { ["name"] = "Technique: Glyph of Flaming Serpent", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Flaming Serpent.\n\nGlyph of Flaming Serpent\nMinor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Searing Totem now resembles Vol'jin's Serpent Ward.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104238] = { ["name"] = "Technique: Glyph of the Compy", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of the Compy.\n\nGlyph of the Compy\nMinor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Hex now transforms enemies into a Compy.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104239] = { ["name"] = "Technique: Glyph of Elemental Familiars", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Elemental Familiars.\n\nGlyph of Elemental Familiars\nMinor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nSummons a random Fire, Water, or Nature familiar. Familiars of different types have a tendency to fight each other.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104240] = { ["name"] = "Technique: Glyph of Astral Fixation", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Astral Fixation.\n\nGlyph of Astral Fixation\nMinor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nAstral Recall now takes you to your capital's Earthshrine.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104241] = { ["name"] = "Technique: Glyph of Rain of Frogs", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Rain of Frogs.\n\nGlyph of Rain of Frogs\nMinor Glyph\nClasses: Shaman\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou summon a rain storm of frogs at your targeted location.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104242] = { ["name"] = "Technique: Glyph of the Raging Whirlwind", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of the Raging Whirlwind.\n\nGlyph of the Raging Whirlwind\nMinor Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhirlwind gives you 15 rage over 6 sec, but for that time you no longer generate rage from autoattacks.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104243] = { ["name"] = "Technique: Glyph of the Subtle Defender", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of the Subtle Defender.\n\nGlyph of the Subtle Defender\nMinor Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nRemoves the threat generation bonus from Defensive Stance.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104244] = { ["name"] = "Technique: Glyph of the Watchful Eye", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of the Watchful Eye.\n\nGlyph of the Watchful Eye\nMinor Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIntervene will now target the party or raid member with the lowest health within 25 yards.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104245] = { ["name"] = "Technique: Glyph of the Weaponmaster", ["text"] = "Requires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of the Weaponmaster.\n\nGlyph of the Weaponmaster\nMinor Glyph\nClasses: Warrior\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Shout abilities cause the appearance of your weapon to change to that of a random weapon from your primary bag for 10 min.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104246] = { ["name"] = "Reins of the Kor'kron War Wolf", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 90\nRequires Journeyman Riding\nUse: Teaches you how to summon a Kor'kron War Wolf. This is a ground mount." }
entries[104253] = { ["name"] = "Kor'kron Juggernaut", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 90\nRequires Journeyman Riding\nUse: Teaches you how to summon a Kor'kron Juggernaut. This is a ground mount.\nSummons and dismisses the Kor'kron Juggernaut." }
