entries[104280] = { ["name"] = "Technique: Glyph of Focused Fire", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of Focused Fire.\n\nGlyph of Focused Fire\nMinor Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nFocus Fire charges apply a visual to you for each charge active.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
entries[104281] = { ["name"] = "Technique: Glyph of Enduring Deceit", ["text"] = "Binds when picked up\nUnique\nRequires Inscription (500)\nUse: Teaches you how to inscribe a Glyph of the Enduring Deceit.\n\nGlyph of Enduring Deceit\nMajor Glyph\nClasses: Hunter\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nCamouflage also reduces spell damage taken by 10%.\nSell Price:\nRequires Light Parchment , Ink of Dreams (3)" }
