entries[104285] = { ["name"] = "Weapon - Sword_2H_Mogu_C_01 - Blue (1H)(Earth Effect)", ["text"] = "One-Hand Sword\n2 - 5 Damage Speed 2.80\n(1.25 damage per second)\nDurability 20 / 20\nSell Price:" }
entries[104286] = { ["name"] = "Quivering Firestorm Egg", ["text"] = "Binds to account\n\"A very rare egg that looks ready to hatch. Elder Anli at The Arboretum will definitely want to see this.\"" }
entries[104287] = { ["name"] = "Windfeather Plume", ["text"] = "Binds to account\nRequires Level 85\nUse: Increases speed while mounted on a ground mount by 30% for 1 hour. Only usable in Pandaria.\n\"The feathers of the Windfeather Crane are surprisingly light to the touch and will fly away with the slightest breeze.\"" }
entries[104288] = { ["name"] = "Condensed Jademist", ["text"] = "Binds when picked up\nUnique (5)\nRequires Level 90\nUse: Surround yourself with a heavy mist, allowing you to blend into the shadows for 10 sec. (5 Min Cooldown)\n\"The Jademist Dancers are known to blend seamlessly into the fog surrounding the island.\"" }
entries[104289] = { ["name"] = "Faintly-Glowing Herb", ["text"] = "Binds when picked up\nUnique (10)\nDuration: 1 day (real time)\nRequires Level 90\nUse: Eat the herb, restoring 30000 health every 1 sec. for 10 sec.\n\"This herb appears to be infused with a natural enchantment.\"" }
entries[104290] = { ["name"] = "Sticky Silkworm Goo", ["text"] = "Binds when picked up\nUnique (10)\nRequires Level 90\nUse: Coat an enemy in sticky silk, immobilizing even the strongest creatures for 20 sec. (5 Min Cooldown)\n\"The silkworms of the Timeless Isle have adapted a strange and very powerful silk used to catch prey.\"" }
entries[104291] = { ["name"] = "Swarmling of Gu'chi", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss your Gu'chi Swarmling." }
entries[104292] = { ["name"] = "Partially-Digested Meal", ["text"] = "Binds when picked up\n\"This snake obviosly ate far too much in one sitting, as the food appears to be mostly intact and undigested.\"\n<Right Click to Open>" }
entries[104293] = { ["name"] = "Scuttler's Shell", ["text"] = "Binds when picked up\nUnique (10)\nUse: Cover your head with a brightly-colored shell, reducing the radius at which enemies will detect you for 1 hour. (5 Min Cooldown)\n\"The shimmering shells of the spineclaws are useful for confusing would-be predators.\"\nSell Price:" }
entries[104294] = { ["name"] = "Rime of the Time-Lost Mariner", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Sing the haunting melody of the crew lost on the Dread Ship Vazuvius. (2 Hrs Cooldown)" }
entries[104295] = { ["name"] = "Harmonious Porcupette", ["text"] = "Binds when picked up\nRequires Emperor Shaohao\n- Revered\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Harmonious Porcupette." }
entries[104296] = { ["name"] = "Ordon Ceremonial Robes", ["text"] = "Binds when picked up\n\"This ornate enchanted cloth can be broken down into useful materials.\"\n<Right Click to Open>" }
entries[104297] = { ["name"] = "Blazing Sigil of Ordos", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Unleash molten fury on all critters within 40 yards.\nSell Price:" }
entries[104298] = { ["name"] = "Ordon Death Chime", ["text"] = "Binds when picked up\nUnique\nTrinket\nRequires Level 90\nUse: Charge at an enemy, inflicting 50000 Fire damage to enemies within 8 yards and knocking them down for 3 sec. (2 Min Cooldown)\n\"The Ordon ring these chimes before a sacrifice is made to Ordos.\"\nSell Price:" }
entries[104299] = { ["name"] = "Falling Flame", ["text"] = "Binds when picked up\nUnique\nRequires Level 90\nUse: Launches the user far into the distance as a blazing meteor. (1 Hour Cooldown)\n50 Charges\n\"A white-hot shard found at the core of Cinderfall.\"\nSell Price:" }
entries[104300] = { ["name"] = "Knife_1h_firelandsraid_d_01", ["text"] = "Binds when picked up\nOff Hand Dagger\n8 - 16 Damage Speed 1.80\n(6.67 damage per second)\nDurability 25 / 25\nSell Price:" }
entries[104301] = { ["name"] = "Knife_1h_firelandsraid_d_01", ["text"] = "Binds when picked up\nMain Hand Dagger\n8 - 16 Damage Speed 1.80\n(6.67 damage per second)\nDurability 25 / 25\nSell Price:" }
entries[104302] = { ["name"] = "Blackflame Daggers", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Wear the Blackflame Daggers, signifying your allegiance to Ordos. (1 Hour Cooldown)\n\"Ceremonial daggers used by champions of Ordos.\"\nSell Price:" }
entries[104303] = { ["name"] = "Rain Stone", ["text"] = "Binds when picked up\nUnique\nUse: Place a Rain Stone that will summon an unnatural rain storm in the surrounding area for 10 min. (1 Hour Cooldown)\n50 Charges\n\"The playful water spirits of Pandaria have a curious connection to the weather.\"\nSell Price:" }
entries[104304] = { ["name"] = "Blizzard Stone", ["text"] = "Binds when picked up\nUnique\nUse: Place a Blizzard Stone that will summon an unnatural snow storm in the surrounding area for 10 min. (1 Hour Cooldown)\n50 Charges\n\"High-ranking Ordon chanters can control the weather, ensuring that snow and rain never fall on the eternal fires of the Ordon Sanctuary.\"\nSell Price:" }
entries[104305] = { ["name"] = "Ashen Stone", ["text"] = "Binds when picked up\nUnique\nUse: Place an Ashen Stone that will summon an ash storm in the surrounding area for 10 min. (1 Hour Cooldown)\n50 Charges\n\"Before attacking, the Ordon yaungol will often summon a storm of ash to blind their foes.\"\nSell Price:" }
entries[104306] = { ["name"] = "Sunset Stone", ["text"] = "Binds when picked up\nUnique\nUse: Place a Sunset Stone that will change the time of day to sunset in the surrounding area for 10 min. (1 Hour Cooldown)\n50 Charges\n\"An odd, and potentially quite dangerous, curio capable of stopping the flow of time in a small area.\"\nSell Price:" }
entries[104307] = { ["name"] = "Jadefire Spirit", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss your Jadefire Spirit." }
entries[104308] = { ["name"] = "Akolik's Acid-Soaked Robes", ["text"] = "Binds when picked up\nChest Cloth\n2703 Armor\n+3,121 Stamina\n+1,840 Intellect\n+ 1,267 Critical Strike\n+ 1,267 Mastery\n\nRed Socket\nRed Socket\nYellow Socket\nSocket Bonus: + 180 Intellect\n\nDurability 165 / 165\nRequires Level 90\nSell Price:" }
entries[104309] = { ["name"] = "Eternal Kiln", ["text"] = "Binds when picked up\nToy\nUse: Places an Eternal Kiln that increases the spirits of those nearby by 4 and allows cooking. (30 Min Cooldown)\n\"Followers of Ordos carry small cauldrons of fire with them for long journeys into the wilderness.\"" }
entries[104311] = { ["name"] = "Legplates of Unthinking Strife", ["text"] = "Binds when picked up\nLegs Plate\n5720 Armor\n+1,840 Strength\n+3,121 Stamina\n+ 1,288 Haste\n+ 1,232 Mastery\n\nBlue Socket\nBlue Socket\nRed Socket\nSocket Bonus: + 180 Strength\n\nDurability 120 / 120\nRequires Level 90\nSell Price:" }
entries[104312] = { ["name"] = "Strange Glowing Mushroom", ["text"] = "Binds when picked up\nUnique (20)\nRequires Level 90\nUse: Heals the user for 5% of maximum health and restores 5% of a class-specific power type every 2 sec for 10 sec.\n\"An odd mushroom found deep within the Cavern of Lost Spirits.\"" }
entries[104313] = { ["name"] = "Golden Moss", ["text"] = "Binds when picked up\nUnique\nTrinket\nRequires Level 85\nEquip: May cause extra gold to drop whenever you kill a target that yields experience or honor. (Proc chance: 10%, 10m cooldown)\n\"The moss is flecked with gold and other precious minerals that have slowly built up over thousands of years in the damp caverns.\"\nSell Price:" }
entries[104314] = { ["name"] = "Dragon P.I.E.", ["text"] = "Use: A surprisingly potent alcoholic beverage.\n\"Handcrafted by Grimthorn Redbeard.\"\nSell Price:" }
entries[104316] = { ["name"] = "Spectral Grog", ["text"] = "Use: Transform into a spectral pirate and gets you drunk to boot. (3 Sec Cooldown)\n\"Gives off an otherworldly aroma.\"\nSell Price:" }
entries[104317] = { ["name"] = "Rotten Helper Box", ["text"] = "Use: Teaches you how to summon this companion.\nRight Click to summon and dismiss your Rotten Little Helper.\n\nEven rotten helpers are very busy year-round, and only have leisure time during the Feast of Winter Veil." }
entries[104318] = { ["name"] = "Crashin' Thrashin' Flyer Controller", ["text"] = "Binds when picked up\nToy\nUse: Summon and control your Flyer! (30 Sec Cooldown)\nSell Price:" }
entries[104319] = { ["name"] = "Winter Veil Gift", ["text"] = "Binds when picked up\n<Right Click to Open>" }
entries[104320] = { ["name"] = "Cursed Talisman", ["text"] = "Binds when picked up\nUnique\nRequires Level 85\nUse: Banishes the user for 20 sec. (5 Min Cooldown)\n50 Charges\n\"The carvings on the face of the talisman depict a grotto filled with moss. If you squint, you can almost make out a face in the moss bed.\"" }
entries[104321] = { ["name"] = "Captain Zvezdan's Lost Leg", ["text"] = "Binds when picked up\nUnique\nTrinket\nRequires Level 85\nUse: Rap the leg on the ground, summoning the crew of the Barnacle to aid you in combat for 10 min. (1 Hour Cooldown)\nSell Price:" }
entries[104323] = { ["name"] = "The Pigskin", ["text"] = "Binds when picked up\nToy\nUse: Throw the ball to a friendly player. If possible, they will automatically return it.\n\"An inflated pig's bladder wrapped in tough cow leather.\"\nSell Price:" }
entries[104324] = { ["name"] = "Foot Ball", ["text"] = "Binds when picked up\nToy\nUse: Kick the ball to a friendly player. If possible, they will automatically return it.\n\"An inflated kodo bladder wrapped in tough, striped zhevra hide.\"\nSell Price:" }
entries[104325] = { ["name"] = "Tyrannical Gladiator's Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 90\nRequires Artisan Riding\nUse: Teaches you how to summon this mount. This is a flying mount." }
entries[104326] = { ["name"] = "Grievous Gladiator's Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 90\nRequires Artisan Riding\nUse: Teaches you how to summon this mount. This is a flying mount." }
entries[104327] = { ["name"] = "Prideful Gladiator's Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 90\nRequires Artisan Riding\nUse: Teaches you how to summon this mount. This is a flying mount." }
entries[104328] = { ["name"] = "Cauterizing Core", ["text"] = "Binds when picked up\nUnique\nRequires Level 85\nUse: Activate the core, allowing the user to resurrect on death with 20% of health and mana. (1 Hour Cooldown)\n20 Charges\n\"A fiery core that holds the living essence imbued into the Molten Guardian.\"" }
entries[104329] = { ["name"] = "Ash-Covered Horn", ["text"] = "Binds when picked up\nUnique\nToy\nMount\nRequires Level 85\nUse: Summons a ridable but uncontrollable Furious Ashhide Mushan. This is a very, VERY fast mount. (1 Min Cooldown)\n\"Perpetually warm to the touch.\"" }
entries[104330] = { ["name"] = "Warped Warning Sign", ["text"] = "Binds when picked up\nUnique\nRequires Level 90\nUse: Place a Warning Sign that lasts for 1 min. A message can be carved into the sign, causing it to last for 1 hour and making it visible to other players. (3 Sec Cooldown)\n5 Charges\n\"The wood of this sign will not last for long.\"" }
